import {frozenTake,nmrComparison,musicComparison,takeSummary,descriptionText,announceTake} from './lab-takes.js';
import {prepare,probabilities,makeTake} from './quantum.js';
import {tempoInfo} from './studio-tempo.js';
import {renderTake} from './take-renderer.js';
const $=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x)),banks={music:[],studio:[]},selected={music:-1,studio:-1},showAll={music:false,studio:false};
let takeId=0;let audio,source,generation=0,pending=false,playingBench=null,mainSnapshot=null,exportAbort=null;
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function txt(t){download(new Blob([descriptionText(t)],{type:'text/plain;charset=utf-8'}),`Quantum_${t.bench}_description.txt`);}
export function currentTake(bench){if(document.querySelector('#'+bench+'-workbench [aria-invalid="true"]'))throw Error('Fix highlighted settings before audition/export.');if(bench==='studio')return frozenTake(bench,'Final circuit',window.quantumStudio.getConfiguration());const c=window.quantumLab.getSession().config,p=probabilities(prepare(c),c.basis0,c.basis1);return frozenTake(bench,'Final circuit',{...c,probs:p},{sequence:makeTake(p,c.seed),variant:c.exportFlavor==='clean'?'clean':'processed'});}
const config=bench=>bench==='music'?window.quantumLab.getSession().config:window.quantumStudio.getConfiguration();
function status(bench,text){$(bench+'-take-status').textContent=text;}
export function stopPreview(){generation++;pending=false;playingBench=null;mainSnapshot=null;if(source){try{source.stop();source.disconnect();}catch{}source=null;}}
async function listen(t){stopPreview();window.quantumLab.stop();window.quantumStudio.stop();const token=generation,bench=t.bench;pending=true;playingBench=bench;mainSnapshot=JSON.stringify(config(bench));status(bench,'Preparing frozen preview…');try{const Context=globalThis.AudioContext||globalThis.webkitAudioContext;audio??=new Context({sampleRate:44100});await audio.resume();const r=await renderTake(t);if(token!==generation)return;const buffer=await audio.decodeAudioData(await r.blob.arrayBuffer());if(token!==generation)return;source=audio.createBufferSource();source.buffer=buffer;source.connect(audio.destination);source.start();pending=false;status(bench,'Preview only · '+takeSummary(t));source.onended=()=>{if(token===generation){source=null;status(bench,'Preview complete · export the selected frozen version.');}};}catch(e){if(token===generation){stopPreview();status(bench,e.message);}}}
async function exportPreview(t,format){if(exportAbort)return;stopPreview();window.quantumLab.stop();window.quantumStudio.stop();exportAbort=new AbortController();const b=t.bench;$(b+'-preview-cancel').hidden=false;try{status(b,'Rendering selected preview…');const r=await renderTake(t,format,{signal:exportAbort.signal,progress:p=>status(b,`Export ${format.toUpperCase()} · ${Math.round(p*100)}%`)});download(r.blob,`Quantum_${b}_preview.${format}`);if(format==='wav'&&$(b+'-include-txt').checked)txt(t);status(b,`Exported selected preview · ${r.duration.toFixed(2)} s · main settings retained.`);}catch(e){status(b,e.name==='AbortError'?'Export cancelled.':e.message);}finally{exportAbort=null;$(b+'-preview-cancel').hidden=true;}}
const dialog=document.createElement('dialog');dialog.id='comparison-description';dialog.className='comparison-dialog';dialog.setAttribute('aria-labelledby','comparison-description-title');dialog.innerHTML='<button class="text-button dialog-close" aria-label="Close comparison description">✕</button><h2 id="comparison-description-title"></h2><dl><dt>What changes</dt><dd id="comparison-changes"></dd><dt>Held fixed</dt><dd id="comparison-holds"></dd><dt>Observe</dt><dd id="comparison-observe"></dd></dl><p id="comparison-summary"></p><button id="comparison-txt" class="secondary-button">Download explanation TXT</button>';document.body.append(dialog);let described,returnFocus;
function close(){dialog.close?.();dialog.removeAttribute('open');returnFocus?.focus();}
export function describe(t){described=t;returnFocus=document.activeElement;$('comparison-description-title').textContent=t.title||t.label;$('comparison-changes').textContent=t.changes||'Frozen temporary configuration.';$('comparison-holds').textContent=t.holds||'The captured settings, seed and sequence.';$('comparison-observe').textContent=t.observe||'Listen before deciding which version to export.';$('comparison-summary').textContent=takeSummary(t);if(dialog.showModal)dialog.showModal();else dialog.setAttribute('open','');dialog.querySelector('button').focus();}
dialog.querySelector('.dialog-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});$('comparison-txt').onclick=()=>txt(described);
function renderBank(bench){const s=$(bench+'-preview-select');s.replaceChildren();banks[bench].forEach((t,i)=>{if(!showAll[bench]&&i<banks[bench].length-3&&i!==selected[bench])return;const o=document.createElement('option');o.value=i;if(t.displayName)o.setAttribute('data-no-translate','');o.textContent=`${i+1}. ${t.displayName||t.title||t.label} · ${t.segments?'A/B pair':takeSummary(t,'')}`;s.append(o);});s.value=selected[bench];$(bench+'-preview-bank').hidden=!banks[bench].length;const name=$(bench+'-preview-name');if(name)name.value=banks[bench][selected[bench]]?.displayName||'';document.dispatchEvent(new window.CustomEvent('lab:previews',{detail:bench}));}
function save(t){const b=t.bench,copies=t.segments?[t,...t.segments.map(s=>({...s,changes:t.changes,holds:t.holds,observe:t.observe}))]:[t];for(const c of copies)banks[b].push({...copy(c),takeId:++takeId});selected[b]=banks[b].length-copies.length;renderBank(b);status(b,'Preview only · choose a frozen version to audition or export.');}
for(const bench of ['music','studio']){const transport=document.querySelector(bench==='music'?'#music-workbench .transport':'.studio-transport'),exportPanel=$(bench==='music'?'music-exports':'studio-exports'),summary=document.createElement('div');summary.className='export-snapshot';summary.innerHTML=`<span id="${bench}-current-summary"></span><button id="${bench}-audio-options" class="text-button" aria-expanded="false">Audio options</button><label><input id="${bench}-include-txt" type="checkbox" checked> WAV + explanation TXT</label>`;transport.append(summary);
 const audioOptions=document.createElement('details');audioOptions.id=bench+'-audio-details';audioOptions.className='compact-audio-options';audioOptions.innerHTML='<summary>Audio export options</summary>';transport.after(audioOptions);audioOptions.append(exportPanel.querySelector('.export-grid>section'));$(bench+'-audio-options').onclick=()=>{audioOptions.open=!audioOptions.open;$(bench+'-audio-options').setAttribute('aria-expanded',String(audioOptions.open));};const currentTxt=document.createElement('button');currentTxt.className='secondary-button';currentTxt.textContent='Download current description TXT';currentTxt.onclick=()=>{try{txt(currentTake(bench));}catch(e){status(bench,e.message);}};audioOptions.append(currentTxt);
 const bank=document.createElement('section');bank.id=bench+'-preview-bank';bank.className='preview-bank';bank.hidden=true;bank.innerHTML=`<h3>Preview only · choose what to keep</h3><label>Saved audition <select id="${bench}-preview-select"></select></label><div class="studio-buttons"><button id="${bench}-preview-listen" class="secondary-button">Listen to this preview</button><button id="${bench}-preview-wav" class="secondary-button">Export this preview · WAV</button><button id="${bench}-preview-mp3" class="secondary-button">MP3</button><button id="${bench}-preview-info" class="text-button">Description</button><button id="${bench}-preview-txt" class="text-button">TXT ↓</button><button id="${bench}-preview-remove" class="text-button">Remove selected</button><button id="${bench}-preview-cancel" class="text-button" hidden>Cancel export</button></div><p>In-memory frozen settings from the beginning. Live slider automation is not recorded. Current export uses the current circuit.</p>`;audioOptions.after(bank);const message=document.createElement('p');message.id=bench+'-take-status';message.className='take-status';message.setAttribute('role','status');bank.after(message);const chosen=()=>banks[bench][selected[bench]];
 $(bench+'-preview-select').onchange=e=>{stopPreview();selected[bench]=Number(e.target.value);renderBank(bench);status(bench,'Selected · '+takeSummary(chosen()));};$(bench+'-preview-listen').onclick=()=>chosen()&&listen(chosen());for(const f of ['wav','mp3'])$(bench+'-preview-'+f).onclick=()=>chosen()&&exportPreview(chosen(),f);$(bench+'-preview-info').onclick=()=>chosen()&&describe(chosen());$(bench+'-preview-txt').onclick=()=>chosen()&&txt(chosen());$(bench+'-preview-cancel').onclick=()=>exportAbort?.abort();$(bench+'-preview-remove').onclick=()=>{stopPreview();banks[bench].splice(selected[bench],1);selected[bench]=Math.min(selected[bench],banks[bench].length-1);renderBank(bench);};
 const rename=document.createElement('div');rename.className='preview-rename';rename.innerHTML=`<label>Preview name <input id="${bench}-preview-name" type="text" maxlength="60"></label><button id="${bench}-preview-rename" class="secondary-button">Rename preview</button><label><input id="${bench}-preview-all" type="checkbox"> Show all auditions</label>`;bank.append(rename);const scope=document.createElement('p');scope.className='preview-scope-note';scope.textContent='Temporary list: auditions are lost when this page closes. Download sound or its description to keep a version.';bank.append(scope);$(bench+'-preview-rename').onclick=()=>{if(chosen()){chosen().displayName=$(bench+'-preview-name').value.trim().slice(0,60);renderBank(bench);}};$(bench+'-preview-all').onchange=e=>{showAll[bench]=e.target.checked;renderBank(bench);};
 exportPanel.querySelectorAll('.export-grid>section').forEach(s=>{const d=document.createElement('details');d.className='export-category';const summary=document.createElement('summary');summary.textContent=s.querySelector('h3').textContent;s.before(d);d.append(summary,s);});
}
function update(){for(const b of ['music','studio'])try{const t=currentTake(b);$(b+'-current-summary').textContent=takeSummary(t,'WAV / MP3')+(b==='music'&&t.config.exportFlavor==='both'?' · Both: separate Clean + Processed files':'');}catch{$(b+'-current-summary').textContent='Fix highlighted settings before export.';}}
document.addEventListener('lab:take',e=>save(e.detail));for(const b of ['music','studio'])document.addEventListener(b+':configuration',e=>{if(playingBench===b&&JSON.stringify(e.detail)!==mainSnapshot){stopPreview();status(b,'Preview stopped: settings changed. Saved version retained.');}update();});for(const type of ['input','change'])document.addEventListener(type,e=>{if((source||pending)&&e.target.closest('#music-workbench,#studio-workbench')&&!e.target.closest('.preview-bank,.export-snapshot'))stopPreview();queueMicrotask(update);},true);update();
for(const [id,b,k] of [['compare','music','tuning'],['m-fx-compare','music','fx'],['s-compare-t2','studio','t2'],['s-compare-echo','studio','echo'],['s-compare-fx','studio','fx'],['s-compare-tuning','studio','tuning'],['s-compare-tempo','studio','tempo']]){const button=$(id),spec=()=>{const t=currentTake(b);return b==='music'?musicComparison(t.config,t.sequence,k):nmrComparison(t.config,k);};button.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();try{const t=spec();announceTake(t);listen(t);}catch(e){status(b,e.message);}},true);const info=document.createElement('button');info.className='text-button comparison-info';info.textContent='Comparison details';info.onclick=()=>{try{describe(spec());}catch(e){status(b,e.message);}};button.after(info);}
const study=document.createElement('button');study.id='s-study-decay';study.className='secondary-button';study.textContent='Study decay · fixed BPM / no pulse';$('s-compare-t2').parentElement.before(study);study.onclick=()=>{const c=config('studio');c.tempo={...c.tempo,bpm:tempoInfo(c).bpm,mode:'fixed',rhythm:false,sync:false};window.quantumStudio.setConfiguration(c);status('studio','Decay study: fixed BPM, pulse off. Model-linked rhythm remains available.');};
const badge=document.createElement('p');badge.className='frozen-badge';badge.textContent='A/B: BPM, pulse depth, pitch, level and duration frozen';study.after(badge);
const apply=document.createElement('button');apply.id='s-apply-audition';apply.className='secondary-button';apply.textContent='Apply & audition';$('s-play').after(apply);apply.onclick=()=>window.quantumStudio.auditionCurrent();
for(const q of [0,1])for(const k of ['t2','star']){const note=document.createElement('small');note.id=`s-${k}${q}-adjustment`;note.className='parameter-adjustment';note.setAttribute('role','status');$('s-'+k+q).after(note);}const tau=document.createElement('small');tau.id='s-tau-adjustment';tau.className='parameter-adjustment';tau.setAttribute('role','status');$('s-tauMs').after(tau);
$('studio-audio-details').append(document.querySelector('.nmr-tempo-detail'));document.querySelector('.studio-transport').after($('s-progress'));
for(const id of ['play','stop','s-play','s-stop','s-apply-audition','music-wav','music-mp3','s-wav','s-mp3'])$(id).addEventListener('click',stopPreview,true);
$('s-pause').addEventListener('click',async e=>{if(!source||!audio)return;e.stopImmediatePropagation();if(audio.state==='running'){await audio.suspend();status('studio','Frozen preview paused.');}else{await audio.resume();status('studio','Preview only · resumed.');}},true);
document.addEventListener('lab:activated',stopPreview);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPreview();});window.addEventListener('pagehide',stopPreview);
window.quantumWorkflow={exported(t,f){if(f==='wav'&&$(t.bench+'-include-txt').checked)txt(t);},describe,stopPreview,getPreviews:b=>copy(banks[b])};
